import type { ComponentChildren } from 'preact';
import { FEATURES } from '../../config';
import { Icon } from '../icons';
import { back } from '../router';

export function AppBar({
  title,
  sub,
  onBack,
  right,
}: {
  title: string;
  sub?: string;
  onBack?: boolean | (() => void);
  right?: ComponentChildren;
}) {
  return (
    <header class="appbar">
      {onBack && (
        <button class="iconbtn" aria-label="뒤로" onClick={() => (typeof onBack === 'function' ? onBack() : back())}>
          <Icon name="back" />
        </button>
      )}
      <div class="grow">
        <h1>{title}</h1>
        {sub && <div class="sub">{sub}</div>}
      </div>
      {right}
    </header>
  );
}

const TABS = [
  { href: '/', label: '홈', icon: 'home' },
  { href: '/assess', label: '평가', icon: 'camera' },
  { href: '/progress', label: '경과', icon: 'chart' },
  ...(FEATURES.rehab === 'off' ? [] : [{ href: '/rehab', label: '재활', icon: 'activity' }]),
  { href: '/settings', label: '설정', icon: 'settings' },
];

export function TabBar({ active }: { active: string }) {
  return (
    <div class="tabbar">
      <nav aria-label="주 메뉴" style={{ gridTemplateColumns: `repeat(${TABS.length}, 1fr)` }}>
        {TABS.map((t) => (
          <a class="tab" href={`#${t.href}`} aria-current={active === t.href ? 'page' : undefined}>
            <Icon name={t.icon} />
            {t.label}
          </a>
        ))}
      </nav>
    </div>
  );
}

export function Segmented<T extends string>({
  value,
  options,
  onChange,
  label,
}: {
  value: T;
  options: readonly { value: T; label: string }[];
  onChange: (v: T) => void;
  label: string;
}) {
  return (
    <div class="seg" role="group" aria-label={label}>
      {options.map((o) => (
        <button type="button" aria-pressed={o.value === value} onClick={() => onChange(o.value)}>
          {o.label}
        </button>
      ))}
    </div>
  );
}

export function Notice({ tone = 'info', children }: { tone?: 'info' | 'warn' | 'danger' | 'good'; children: ComponentChildren }) {
  const icon = tone === 'good' ? 'check' : tone === 'info' ? 'info' : 'alert';
  const color =
    tone === 'danger'
      ? 'var(--critical)'
      : tone === 'warn'
        ? 'var(--warning-ink)'
        : tone === 'good'
          ? 'var(--good-ink)'
          : 'var(--accent-ink)';
  return (
    <div class="notice">
      <span style={{ color }}>
        <Icon name={icon} />
      </span>
      <div class="grow">{children}</div>
    </div>
  );
}

/** "Measured / estimated" marker attached to every derived clinical score. */
export function EstBadge() {
  return <span class="est">추정</span>;
}

export function Meter({ label, value }: { label: string; value: number }) {
  const v = Math.max(0, Math.min(100, value));
  return (
    <div class="meter" role="meter" aria-label={label} aria-valuemin={0} aria-valuemax={100} aria-valuenow={v}>
      <span class="ink2">{label}</span>
      <div class="track">
        <div class="fill" style={{ width: `${v}%` }} />
      </div>
      <span class="val tabular">{v}%</span>
    </div>
  );
}

export function RegionMeters({ regional }: { regional: { forehead: number; eye: number; midface: number; mouth: number } }) {
  return (
    <div class="stack">
      <Meter label="이마" value={regional.forehead} />
      <Meter label="눈" value={regional.eye} />
      <Meter label="코·볼" value={regional.midface} />
      <Meter label="입" value={regional.mouth} />
      <p class="xsmall muted" style={{ margin: 0 }}>
        마비 쪽이 건강한 쪽만큼 움직이면 100%입니다. 낮을수록 마비 쪽 움직임이 약합니다.
      </p>
    </div>
  );
}
